import { expect, test, type Locator, type Page } from '@playwright/test'
import { readFile, writeFile } from 'node:fs/promises'
import { join } from 'node:path'
import { MAIN, installGateway, logs } from './support/real-conversation-gateway'
import { officeHash } from './support/office-fixtures'

// Opt-in acceptance with the real multi-page Office files generated by:
// python scripts/testing/create_workbench_preview_fixtures.py --output <directory>
// OPENSQUILLA_ANNOTATION_FIXTURE_DIR=<directory> npx playwright test annotation-placement
// The Office parsers/renderers are real; only the unrelated Gateway/model is isolated.
const directory = process.env.OPENSQUILLA_ANNOTATION_FIXTURE_DIR
const files = {
  docx: ['26-report.docx', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'],
  pptx: ['27-deck.pptx', 'application/vnd.openxmlformats-officedocument.presentationml.presentation'],
  xlsx: ['28-workbook.xlsx', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'],
} as const
type Box = { x: number; y: number; width: number; height: number }

async function box(locator: Locator): Promise<Box> {
  const result = await locator.boundingBox()
  expect(result).not.toBeNull()
  return result!
}

function separation(a: Box, b: Box) {
  return Math.hypot(Math.max(0, a.x - b.x - b.width, b.x - a.x - a.width),
    Math.max(0, a.y - b.y - b.height, b.y - a.y - a.height))
}

async function assertAttached(workbench: Locator, requireGap = false) {
  const card = workbench.locator('.annotation-comment')
  const selected = workbench.locator('[data-office-selected]')
  await expect(card).toBeVisible()
  await expect(selected).toBeVisible()
  await expect.poll(async () => separation(await box(card), await box(selected)),
    { message: 'The editor must stay beside the selected content, including after layout changes.' }).toBeLessThanOrEqual(12)
  if (requireGap) expect(separation(await box(card), await box(selected)),
    'The editor must not cover its target when the viewport has room.').toBeGreaterThanOrEqual(5)
  const bounds = await box(workbench.locator('.office-preview__viewport'))
  const editor = await box(card)
  expect(editor.x).toBeGreaterThanOrEqual(bounds.x - 1)
  expect(editor.y).toBeGreaterThanOrEqual(bounds.y - 1)
  expect(editor.x + editor.width).toBeLessThanOrEqual(bounds.x + bounds.width + 1)
  expect(editor.y + editor.height).toBeLessThanOrEqual(bounds.y + bounds.height + 1)
  const grid = workbench.locator('[data-xlsx-viewport-input]')
  if (await grid.isVisible()) {
    const gridBounds = await box(grid)
    expect(editor.y + editor.height, 'The editor must leave the worksheet tabs accessible.')
      .toBeLessThanOrEqual(gridBounds.y + gridBounds.height - 7)
  }
}

async function dragText(page: Page, text: Locator, end: Locator = text) {
  const rect = await box(text), endRect = await box(end)
  await page.mouse.move(rect.x + 2, rect.y + rect.height / 2)
  await page.mouse.down()
  await page.mouse.move(endRect.x + endRect.width * .45, endRect.y + endRect.height / 2, { steps: 14 })
  await page.mouse.up()
}

async function geometry(workbench: Locator) {
  return workbench.evaluate(element => Object.fromEntries(
    ['.office-preview__canvas', '.office-preview__canvas canvas', '[data-office-annotation-layer]', '[data-office-selected]', '[data-ooxml-selection-run]', '.annotation-comment']
      .map(selector => {
        const node = element.querySelector<HTMLElement>(selector)
        return [selector, node ? { bounds: node.getBoundingClientRect().toJSON(), style: node.getAttribute('style') } : null]
      })))
}

test.afterEach(async ({ page }, testInfo) => {
  const events = logs.get(page)
  if (!events) return
  const path = testInfo.outputPath('gateway-and-render-events.json')
  await writeFile(path, JSON.stringify(events, null, 2))
  await testInfo.attach('gateway-and-render-events', { path, contentType: 'application/json' })
})

for (const format of ['docx', 'pptx', 'xlsx'] as const) {
  test(`${format} real-file annotation follows content through scrolling and zoom`, async ({ page }, testInfo) => {
    test.skip(!directory, 'Set OPENSQUILLA_ANNOTATION_FIXTURE_DIR to the generated preview gallery.')
    test.setTimeout(120_000)
    await page.setViewportSize({ width: 1560, height: 1000 })
    await page.addInitScript(() => {
      window.OPENSQUILLA_FEATURES = { ...(window.OPENSQUILLA_FEATURES || {}),
        artifactWorkbench: true, officePromptAnnotations: true }
    })
    const gateway = await installGateway(page)
    const [name, mime] = files[format]
    const bytes = await readFile(join(directory!, name))
    await testInfo.attach('real-office-fixture', { contentType: 'application/json',
      body: JSON.stringify({ name, size: bytes.byteLength, sha256: officeHash(bytes) }) })
    const documentId = `doc_real_placement_${format}`
    const artifact = gateway.registerDocument(MAIN, documentId, name, {
      format, mime, workspacePath: `preview-gallery/${name}`,
      sha256: officeHash(bytes), size: bytes.byteLength, annotation: true,
    })
    gateway.appendHistory(MAIN, { role: 'assistant', id: 'real-placement-delivery',
      text: 'Real Office fixture for annotation placement.', artifacts: [artifact] })
    for (const path of [`artifact-documents/${documentId}`, `artifacts/art-${documentId}`]) {
      await page.route(`**/api/v1/${path}**`, route => route.fulfill({
        contentType: mime, body: bytes, headers: { 'content-length': String(bytes.byteLength) },
      }))
    }
    await page.goto(`/control/chat?session=${encodeURIComponent(MAIN)}`)
    await page.locator('.msg-artifact-chip', { hasText: name })
      .getByRole('button', { name: `Open ${name}` }).click()
    const workbench = page.getByTestId('workbench-host')
    const card = workbench.locator('.annotation-comment')
    const selected = workbench.locator('[data-office-selected]')
    const viewport = workbench.locator('.office-preview__viewport')
    await expect(workbench.locator('.office-preview__canvas canvas').first()).toBeVisible({ timeout: 60_000 })
    await workbench.getByRole('button', { name: 'Annotate', exact: true }).click()
    await expect(workbench.locator('.office-preview__guide')).toBeVisible()
    if (format === 'xlsx') {
      const grid = await box(workbench.locator('[data-xlsx-viewport-input]'))
      await page.mouse.move(grid.x + 80, grid.y + 75)
      await page.mouse.down()
      await page.mouse.move(grid.x + 290, grid.y + 115, { steps: 12 })
      await page.mouse.up()
    } else if (format === 'docx') {
      await workbench.locator('[data-ooxml-selection-run]').filter({ hasText: /^Synthetic\s*$/ }).first().click({ timeout: 10_000 })
    } else {
      // One click must select the Word paragraph, as well as a PowerPoint object.
      await workbench.locator('[data-ooxml-selection-run]').first().click()
    }
    await assertAttached(workbench, true)
    if (format === 'docx') await expect(card).toHaveAttribute('aria-label', /Synthetic.*preview.*report.*合成报告/)
    const instruction = `Preserve this ${format} instruction while scrolling and zooming.`
    await card.locator('textarea').fill(instruction)
    await assertAttached(workbench, true)
    await page.screenshot({ path: testInfo.outputPath('selected-editor-attached.png') })
    expect(gateway.requests.filter(request => request.method === 'chat.send')).toHaveLength(0)

    const beforeZoom = await box(selected)
    const geometryBefore = await geometry(workbench)
    await workbench.getByRole('button', { name: 'Zoom in', exact: true }).click()
    try {
      await expect.poll(async () => (await box(selected)).width).toBeGreaterThan(beforeZoom.width + 1)
    } finally {
      const path = testInfo.outputPath('zoom-geometry.json')
      await writeFile(path, JSON.stringify({ before: geometryBefore, after: await geometry(workbench) }, null, 2))
      await testInfo.attach('zoom-geometry', { contentType: 'application/json', path })
    }
    await assertAttached(workbench, true)
    await expect(card.locator('textarea')).toHaveValue(instruction)
    // Slides initially fit the page. Zoom until the real viewport can scroll.
    if (format === 'pptx') {
      for (let i = 0; i < 7; i++) {
        const scrollable = await viewport.evaluate(element => element.scrollHeight - element.clientHeight)
        if (scrollable >= 90) break
        const width = (await box(workbench.locator('.office-preview__canvas canvas').first())).width
        await workbench.getByRole('button', { name: 'Zoom in', exact: true }).click()
        await expect.poll(async () => (await box(workbench.locator('.office-preview__canvas canvas').first())).width).toBeGreaterThan(width)
      }
    }
    await assertAttached(workbench)
    const beforeScroll = await box(selected)
    const scrollSurface = format === 'xlsx' ? workbench.locator('[data-xlsx-viewport-input]') : viewport
    // Change the actual renderer viewport, not the window or an artificial CSS transform.
    await scrollSurface.evaluate(element => { element.scrollTop += 40 })
    await expect.poll(async () => (await box(selected)).y).toBeLessThan(beforeScroll.y - 20)
    await assertAttached(workbench)
    await expect(card.locator('textarea')).toHaveValue(instruction)
    await page.screenshot({ path: testInfo.outputPath('after-scroll-and-zoom.png') })
    expect(gateway.requests.filter(request => request.method === 'chat.send')).toHaveLength(0)

    if (format !== 'pptx') {
      if (format === 'docx') {
        // At fit width this two-page fixture is almost the viewport's height.
        // Enlarge it enough that scrolling can genuinely move the title out.
        for (let i = 0; i < 3; i++) {
          const width = (await box(workbench.locator('.office-preview__canvas canvas').first())).width
          await workbench.getByRole('button', { name: 'Zoom in', exact: true }).click()
          await expect.poll(async () => (await box(workbench.locator('.office-preview__canvas canvas').first())).width).toBeGreaterThan(width)
        }
        await assertAttached(workbench)
      }
      const returnScroll = await scrollSurface.evaluate(element => element.scrollTop)
      await scrollSurface.evaluate(element => { element.scrollTop += 600 })
      await expect(selected).not.toBeVisible()
      const visibleBounds = await box(viewport)
      await expect.poll(async () => (await box(card)).y - visibleBounds.y,
        { message: 'When the target leaves above the viewport, keep the draft at that edge.' }).toBeLessThanOrEqual(20)
      await expect(card.locator('textarea')).toHaveValue(instruction)
      await scrollSurface.evaluate((element, value) => { element.scrollTop = value }, returnScroll)
      await assertAttached(workbench)
    }

    // Clicking the right arrow records, and reopening from the left restores a located editor.
    await card.locator('.annotation-comment__record').click()
    const recorded = page.getByTestId('composer-prompt-annotations')
    await expect(recorded).toContainText(instruction)
    await expect(card).not.toBeVisible()
    expect(gateway.requests.filter(request => request.method === 'chat.send')).toHaveLength(0)
    await recorded.locator('.chat-prompt-annotation-chip__main').click()
    await assertAttached(workbench)
    await expect(card.locator('textarea')).toHaveValue(instruction)
    await card.getByRole('button', { name: 'Cancel this edit', exact: true }).click()
    await expect(recorded).toContainText(instruction)

    if (format === 'docx') {
      // Dragging a partial run must remain a text selection; it must not be promoted to the whole paragraph.
      if (!await workbench.locator('.office-preview__guide').isVisible()) {
        await workbench.getByRole('button', { name: 'Annotate', exact: true }).click()
      }
      await expect(workbench.locator('.office-preview__guide')).toBeVisible()
      const run = workbench.locator('[data-ooxml-selection-run]').filter({ hasText: /^This\s*$/ }).first()
      const end = workbench.locator('[data-ooxml-selection-run]').filter({ hasText: /^contains\s*$/ }).first()
      await dragText(page, run, end)
      await assertAttached(workbench)
      await card.locator('textarea').fill('Change only the dragged words.')
      await card.locator('.annotation-comment__record').click()
      const partial = recorded.locator('.chat-prompt-annotation-chip').filter({ hasText: 'Change only the dragged words.' })
      const target = (await partial.locator('.chat-prompt-annotation-chip__target').textContent())!
      expect(target).toContain('This')
      expect(target).not.toContain('real user data')
      expect(gateway.requests.filter(request => request.method === 'chat.send')).toHaveLength(0)
    }
    if (format === 'xlsx') {
      // A target near the bottom must flip above the selection, without using
      // the worksheet tabs as spare room for the compact or expanded editor.
      await expect(workbench.locator('.office-preview__guide')).toBeVisible()
      const grid = await box(workbench.locator('[data-xlsx-viewport-input]'))
      await page.mouse.click(grid.x + 80, grid.y + grid.height - 65)
      await assertAttached(workbench, true)
      await card.locator('textarea').fill('Keep the worksheet tabs accessible.')
      await assertAttached(workbench, true)
      await page.screenshot({ path: testInfo.outputPath('sheet-edge-editor.png') })
      await card.locator('.annotation-comment__record').click()
      expect(gateway.requests.filter(request => request.method === 'chat.send')).toHaveLength(0)
    }
    await expect(workbench.locator('.annotation-summary')).toHaveCount(0)
    await page.locator('#app-main .chat-send-btn.btn--primary').click()
    await expect.poll(() => gateway.requests.filter(request => request.method === 'chat.send').length).toBe(1)
    expect(JSON.stringify(gateway.requests.find(request => request.method === 'chat.send')?.params)).toContain(instruction)
    expect(gateway.errors).toEqual([])
  })
}
